            /**
             * Base resolver which handles set of resolvers and DOM resolvers registered with gsearchable
             *
             * @author Vlastimil Máca
             * @since
             */
            class GMainSearchResolver {
                //#region events
                on(eventName, fce) {
                    // this is overrided by constructor
                    throw new Error("Method not implemented.");
                }
                off(eventName) {
                    // this is overrided by constructor
                    throw new Error("Method not implemented.");
                }
                active(opts) {
                    this.dispatchEvent('active', arguments);
                }
                reset(opts) {
                    this.dispatchEvent('reset', arguments);
                }
                //#endregion
                constructor(opts) {
                    this.id = "master";
                    /**
                     * permanent resolvers, registered in constructor
                     * @type {IGSearchResolver[]}
                     * @default []
                     */
                    this.permanentResolvers = [];
                    this.useSearchableResolvers = true;
                    this.currentTask = null;
                    this.actDomainSelected = {
                        name: "actDomainSelected",
                        caption: "jres:31750039", //RC 31750039 : Zvolit pro vyhledávání
                        run: (ev, ctx) => {
                            this.searchField?.gsearchfield("setResolver", { resolver: ctx.item.data.resolver });
                            //do not reset field, after selection of this item
                            ctx.searchOptions = ctx.searchOptions || {};
                            ctx.searchOptions.stopReset = true;
                        }
                    };
                    $.extend(this, new GEvents());
                    if (opts != null) {
                        const { resolvers } = opts;
                        if (resolvers != null)
                            for (let i = 0, l = resolvers.length; i < l; i++) {
                                const resolver = resolvers[i];
                                this.addPermanentResolver(resolver.resolve != null ? resolver : new GSearchResolver(resolver));
                            }
                        this.useSearchableResolvers = opts.useSearchableResolvers !== false ? true : false;
                        this.domainResolver = opts.domainResolver !== null ? new GDomainResolver() : null;
                        this.searchField = opts.searchField;
                    }
                }
                setSearchField(searchField) {
                    if (searchField && searchField.hasClass("gsearchfield")) {
                        this.searchField = searchField;
                    }
                    return this.searchField;
                }
                /**
                 * addResolver to subResolvers
                 *
                 * @param {string} id
                 * @param {IGSearchResolver} resolver
                 */
                addPermanentResolver(resolver) {
                    if (this.permanentResolvers.find((it) => it.id === resolver.id) != null) {
                        throw new GError("jres:31750040".format(resolver.id)); //RC 31750040 : Resolver with id: {0} is already registered in search resolver.
                    }
                    else {
                        this.permanentResolvers.push(resolver);
                    }
                }
                /**
                 * removeResolver
                 *
                 * @param {string} id
                 */
                removePermanentResolver(id) {
                    const index = this.permanentResolvers.findIndex((it) => it.id === id);
                    if (index >= 0) {
                        this.permanentResolvers.splice(index, 1);
                        if (this.searchField) {
                            this.searchField.gsearchfield('reset');
                        }
                    }
                }
                getResolvers(input) {
                    const currentResolvers = new Gordic.Data.View(this.permanentResolvers, { key: "id" });
                    if (this.useSearchableResolvers) {
                        const immediateResolversElements = $(".gsearchable");
                        let immediateResolvers;
                        for (let i = 0, l = immediateResolversElements.length; i < l; i++) {
                            immediateResolvers = immediateResolversElements.eq(i).gsearchable("getResolvers", input);
                            if (immediateResolvers != null) {
                                currentResolvers.updateData(immediateResolvers, "update");
                            }
                        }
                    }
                    return currentResolvers.getDataRows(false, "data");
                }
                /**
                 * Finds results for given input
                 *
                 * @param {IGSearchInput} input
                 */
                resolve(input) {
                    //create task and reject old one if not resolved //TODO: here can be made some optimalizations ... 
                    const { domainResolver, currentTask: _oldCurrentTask } = this;
                    if (_oldCurrentTask != null && _oldCurrentTask.getPromise().state() == "pending")
                        _oldCurrentTask.close();
                    const currentTask = this.currentTask = new GSearchResolveTask(input);
                    const searchField = this.setSearchField(input.searchField);
                    ;
                    if (searchField == null)
                        throw new GError("MainSearchResolver doesn't have searchField property set. Please use setSearchField method to set searchField element.");
                    const resolvers = this.getResolvers(input);
                    let searchInResolvers = true;
                    if (domainResolver !== null) {
                        const domains = domainResolver.getDomains(resolvers, input);
                        const detectedDomain = domainResolver.detectImmediateDomain(domains, input);
                        if (detectedDomain != null) { //if input is domain selection, set resolver to field
                            searchField.gsearchfield("setResolver", {
                                resolver: detectedDomain.rankedDomain.resolver,
                                oldInput: detectedDomain.text,
                                newTextInput: detectedDomain.remainingText,
                                rememberPreviousInput: true
                            });
                            searchInResolvers = false;
                            currentTask.finishRegistration();
                        }
                        else {
                            const actDomainSelected = new GAction(this.actDomainSelected);
                            const domainResults = domains.map((dom) => {
                                return {
                                    name: dom.domain.name,
                                    description: dom.domain.description,
                                    confidence: dom.confidence.confidence,
                                    domainId: "domain",
                                    icon: "fa-terminal",
                                    data: dom,
                                    defaultAction: actDomainSelected
                                };
                            });
                            currentTask.registerPartialResult(this, $.Deferred().resolve(new GSearchResolverResult(this.id, domainResults, [{ id: "domain", name: "jres:31750041", icon: "fa-terminal" }] //RC 31750041 : Oblast hledání
                            )).promise());
                        }
                    }
                    if (searchInResolvers) {
                        if (input.text !== "") { //if input is not empty, search also in registred resolvers
                            const resolveFunc = (resolver, task, _input) => {
                                if (!task.wasCancelled()) { //if task is still active, register result of subResolver
                                    const partialResult = resolver.resolve(_input);
                                    task.registerPartialResult(resolver, partialResult);
                                }
                            };
                            setTimeout(() => {
                                for (let i = 0, l = resolvers.length; i < l; i++) {
                                    if (resolvers[i] !== null)
                                        resolveFunc(resolvers[i], currentTask, input);
                                }
                                currentTask.finishRegistration();
                            }, 0);
                        }
                        else {
                            currentTask.finishRegistration();
                        }
                    }
                    return currentTask.getPromise();
                }
                getDomain() {
                    //master nemá domain
                    return null;
                }
            }
