            /**
             * Zkontroluje, zda je zadaný filtr uložen v uživatelském nastavení jako výchozí.
             *
             * @author  DSebesta, TFeik
             * @date    Dávno tomu, 04.06.2020
             *
             * @param {filterpanelFilterOptionsInternal<TFilterData>} [filter]
             * @returns {boolean}
             */
            _isThisIxsMasFavorite(filter) {
                if (filter) {
                    const filterFromStore = this._getDefaultFilterFromStorage();
                    if (filterFromStore) {
                        if (filterFromStore.ixs_mas && filter.ixs_mas === filterFromStore.ixs_mas) {
                            return true;
                        }
                        // 04.06.2020 - TFeik
                        // V případě, kdy ve filtrech není ixs_mas ještě zkusím kompletní porovnání objektů pro případ,
                        // kdy je jako výchozí nastaven statický filtr (bez ixs_mas).
                        else if (filterFromStore.ixs_mas == undefined && filter.ixs_mas == undefined) {
                            if (Gordic.Utils.AreObjectsEqual(filter, filterFromStore)) {
                                return true;
                            }
                        }
                    }
                    // 04.06.2020 - TFeik
                    // Možnost nastavit programátorsky výchozí filtr.
                    else if (filter.gfilterpanel_is_default) {
                        return true;
                    }
                }
                return false;
            }
