                //const content = $.content(this.element) as GContent | undefined;
                if (content && !content.closed) {
                    const elementForResize = content?.element ? content.element[0] : undefined;
                    if (elementForResize) {
                        Gordic.ResizeManager.observe(elementForResize, {
                            id: ResizeElementId,
                            wait: 50,
                            isActive: (contentRect, prevContentRect, lastActiveContentRect) => {
                                if (!lastActiveContentRect) {
                                    return true;
                                }
                                // 20.05.2020 - TFeik
                                // Pokud je šířka 0 (otevře se detail filtru), pak resize neprovádím.
                                if (contentRect.width !== lastActiveContentRect.width && contentRect.width !== 0) {
                                    return true;
                                }
                                return false;
                            },
                            execute: (contentRect, prevContentRect, lastActiveContentRect) => {
                                // 02.04.2020 - TFeik
                                // Pokud už buttonpanel neexistuje, pak končím.
                                if (!Gordic.Utils.WidgetExists('gbuttonpanel', this.mainFilterButton)) {
                                    return;
                                }
                                if (!Gordic.Utils.WidgetExists('gfield', this.vyberPredvolenychFiltru)) {
                                    return;
                                }
                                const parentWidth = contentRect.width;
                                if (parentWidth == undefined) {
                                    return;
                                }
                                let filterWidth;
                                if (parentWidth > 600) {
                                    filterWidth = 400;
                                }
                                else {
                                    filterWidth = 200;
                                }
                                if (filterWidthCurrent != undefined && filterWidthCurrent === filterWidth) {
                                    return;
                                }
                                this.vyberPredvolenychFiltru.width(filterWidth);
                                // 30.03.2020 - TFeik
                                // Pokud měním velikost widgetu, pak chci přepočítat velikosti v button panelu.
                                this.mainFilterButton.gbuttonpanel('updateVisibility' /*, true*/);
                                filterWidthCurrent = filterWidth;
                            }
                        });
                        content?.element.one("contentclose", () => { Gordic.ResizeManager.unobserve(elementForResize, ResizeElementId); });
                    }
                }
                //this.filtrBadge = $.newDiv()
                //    .insertAfter(this.mainFilterButton.find(".js-gbuttonpanel-item.js-hlavniVyhledat")) //g-buttonpanel__left
                //    .glink({
