            // skryje všecko kromě toho co potřebujeme v inline dialogu
            _getFormOnlyWithVisibleRowByFieldName(fieldName) {
                const that = this;
                const tempForm = $.newDiv();
                $(that.options.forms).each((index, element) => {
                    element.form.customClass = "js-FormSKriterii"; // klasa podle ktere pak vyhledávám formy s podmínkami
                    const tabLabel = element.form.tabLabel || "vyplňte tabLabel do options formu"; //vytahá jméno tabu
                    const tabOpened = element.form.tabOpened;
                    $.newDiv()
                        .appendTo(tempForm)
                        .gtab({
                        title: tabLabel,
                        opened: tabOpened ?? true
                    })
                        .gform("createFrom", element); //.gtab({ title: tabLabel, opened: true, })
                });
                const formy = tempForm.findForms(".js-FormSKriterii");
                // 03.03.2021 - TFeik
                // Tady si nejsem jist, jestli flagy mají být.
                formy.findFields().gfield("clear", { filterClear: true, noChange: true });
                that._showHideFields(true, formy);
                const hledanyField = formy.findFields(fieldName);
                hledanyField.gform().show();
                hledanyField.gformsection().show();
                hledanyField.gformrow().show();
                hledanyField.gformrow().findFields().show();
                hledanyField.gfield("model", "validators", this.options.validators);
                hledanyField
                    .parents('.gtab')
                    .gtab('option', 'visible', true)
                    .gtab('option', 'opened', true)
                    .siblings('.g-tab-header')
                    .hide();
                return tempForm;
            }
            // pomocná funkce pro hledání rozdílu v poli
            _findDifrenceBetweenArray(NoveData) {
                const that = this;
                //that.LastValueInnSelboxSVyhledanejmaKriteriema
                //const difference = that.LastValueInnSelboxSVyhledanejmaKriteriema
                //    .filter(function (x) { return !NoveData.includes(x);  })
                //    .concat(NoveData.filter(function (x) { return !that.LastValueInnSelboxSVyhledanejmaKriteriema.includes(x);  }));
                //const difference = $($.extend(true, [], that.LastValueInnSelboxSVyhledanejmaKriteriema)).not($.extend(true, [], NoveData)).get();,
                const difference = [];
                const a1 = that.LastValueInnSelboxSVyhledanejmaKriteriema;
                const a2 = NoveData;
                for (let i = 0; i < a1.length; i++) {
                    let JeVpoli = false;
                    for (let y = 0; y < a2.length; y++) {
                        if (a2[y].fieldName === a1[i].fieldName) {
                            JeVpoli = true;
                        }
                    }
                    if (JeVpoli === false) {
                        difference.push(a1[i]);
                    }
                }
                return difference;
            }
            // funkce pro skrytí nebo zobrazení oblíbených a slectboxu s kritérii
            //private _showHideInternalfunction(favotitesOpened?: boolean) {
            /**
             * funkce pro skrytí nebo zobrazení oblíbených a slectboxu s kritérii
             *
             * @param {filterpanelPoVyhledaniZobrazit} [stavZobrazeniFiltru] Stav, který chceme nastavit. Pokud není vyplněn pak se nastaví stav po vyhledání
             */
            _showHideInternalfunction(stavZobrazeniFiltru /* | 'SkrytVse'*/) {
                //if (favotitesOpened) {
                //    //  that.showHideFavoriteAcrtion.update({ icon: "gi-arrow-double gi-rot270" });
                //    this.favotitesOpened = false;
                //    //that._showHideSearchButtonOnMainRow(true);
                //    //that._favoriteFilteredSelectBoxShow();
                //    if (this.getFiltrBadgeVisibleOnly()) {
                //        this._hideFilteredSelectBoxAndShowBadge();
                //    } else {
                //        this._showFilteredSelectBoxAndHideBadge();
                //    }
                //} else {
                //    //  that.showHideFavoriteAcrtion.update({ icon: "gi-arrow-double gi-rot90" });
                //    this.favotitesOpened = true;
                //    // that._showHideSearchButtonOnMainRow(false);
                //    //that._favoriteFilteredSelectBoxShow();
                //    this._hideFilteredSelectBoxAndShowBadge();
                //    //that._favoriteFilteredSelectBoxHide();
                //}
                let focusTarget;
                const origFavotitesOpened = this.favotitesOpened;
                switch (stavZobrazeniFiltru) {
                    case 'OblibenePodminky':
                        this.favotitesOpened = true;
                        this._hideFilteredSelectBoxAndShowBadge();
                        focusTarget = 'favorites';
                        break;
                    case 'VyhledanePodminkyVBadge':
                        this.favotitesOpened = false;
                        this._hideFilteredSelectBoxAndShowBadge();
                        focusTarget = 'filterButton';
                        break;
                    case 'VyhledanePodminkyVSelectboxu':
                        this.favotitesOpened = false;
                        this._showFilteredSelectBoxAndHideBadge();
                        focusTarget = 'filterButton';
                        break;
                    default:
                        throw 'Nepodporovaný stav zobrazení filtrů.';
                }
                //if (favotitesOpened) {
                //    if (this.getPoVyhledaniZobrazit() === 'VyhledanePodminkyVBadge') {
                //        this._hideFilteredSelectBoxAndShowBadge();
                //    }
                //}
                if (focusTarget) {
                    this.focus(focusTarget);
                }
                //vmaca-11.11.2022- Nemá cenu volat refresh, pokud se nezměnilo, že je favorites opened - zbytečně to bliká
                return origFavotitesOpened !== this.favotitesOpened || this.element.findForms(FormFavoriteName).length === 0 ? this.refreshFavorite() : $.Deferred().resolve().promise();
            }
