            _manageAkceProVymazani() {
                // 11.05.2020 - TFeik
                // Pokud není chování auto pak visible neměním a končím.
                if (this.options.clearFilterButtonVisible != undefined && this.options.clearFilterButtonVisible != 'Auto') {
                    return $.Deferred().resolve().promise();
                }
                // 01.06.2020 - TFeik
                // Vymazání a nastavení hodnot políček manuálně.
                // 21.10.2020 - TFeik
                // Úprava práce a rušení kontrolního divu.
                return this.getInitialValues()
                    .then((initialValues) => {
                    //return this._createKontrolniDiv(/*undefined, 'reset'*/)
                    //    .then(($kontrolniDiv) => {
                    //        // kontrola obsahu hlavího selboxu
                    //        const initialValues: TFilterData = {} as TFilterData;
                    //        $kontrolniDiv
                    //            .findFields()
                    //            .gfield('model', 'collect', initialValues);
                    //        this._removeKontrolniDiv($kontrolniDiv);
                    let show = false;
                    const $vyberPredvolenychFiltruField = this.element.findFields("vyberPredvolenychFiltru");
                    const selectboxHasValue = $vyberPredvolenychFiltruField.gfield("hasValue");
                    if (selectboxHasValue) {
                        const selboxValue = $vyberPredvolenychFiltruField.gfield("getValue");
                        if (!Gordic.Utils.AreObjectsEqual(selboxValue, initialValues)) {
                            //if (!this._isEmptyObject(selboxValue)) {
                            show = true;
                        }
                    }
                    //kontrola favorite
                    if (this.favotitesOpened) {
                        const favorite = this._getCollectOfFavorite(true);
                        // 25.05.2020 - TFeik
                        // Porovnání s extendem přes inicializační hodnoty.
                        if (!Gordic.Utils.AreObjectsEqual($.extend({}, initialValues, favorite), initialValues)) {
                            //if (!this._isEmptyObject(favorite)) {
                            show = true;
                        }
                    }
                    else {
                        // 25.05.2020 - TFeik
                        // Porovnání s extendem přes inicializační hodnoty.
                        if (this.favoriteModel && !Gordic.Utils.AreObjectsEqual($.extend({}, initialValues, this.favoriteModel), initialValues)) {
                            //if (this.favoriteModel && !this._isEmptyObject(this.favoriteModel)) {
                            show = true;
                        }
                    }
                    if (show) {
                        this._shbowAkceProVybmazani();
                    }
                    else {
                        this._hideAkceProVybmazani();
                    }
                });
            }
            _isEmptyObject(favorite) {
                let empty = true;
                if (!jQuery.isEmptyObject(favorite)) {
                    let maHodnotu = false;
                    for (const key in favorite) {
                        // skip loop if the property is from prototype
                        if (!favorite.hasOwnProperty(key))
                            continue;
                        const obj = favorite[key];
                        if (obj !== undefined && obj !== null && obj !== false) {
                            maHodnotu = true;
                        }
                    }
                    if (maHodnotu) {
                        empty = false;
                    }
                }
                return empty;
            }
            _shbowAkceProVybmazani() {
                this.actions.actVymazatKriteriainFavorite.update({ visible: true });
                //if (!this.favotitesOpened) { 
                this.actions.actVymazatKriteria.update({ visible: true });
                //}
            }
