            getFavoritesWithoutTemp(
            /**
             * (Default: Aktuální režim filterpanelu) Příznak, zda se ukládá favorites pro simple mód.
             * @type {boolean}
             */
            isSimpleMode) {
                let result;
                if (this.gStore) {
                    if (isSimpleMode ?? this.isSimpleMode()) {
                        if (this.options.idSimpleMode?.trim()) {
                            result = this.gStore.get("favoritesSimple." + this.options.idSimpleMode, true); // pokud v gstore nicneni tak použiju defaultní hosnoty
                        }
                        else {
                            result = this.getAllRowsName();
                        }
                    }
                    else {
                        result = this.gStore.get("favorites", true); // pokud v gstore nicneni tak použiju defaultní hosnoty
                    }
                }
                if (!result) {
                    // 02.09.2020 - TFeik
                    // Možnost přidat všechny políčka najednou pomocí 'all'.
                    if (this.options.favorites === 'all') {
                        result = this.getAllRowsName();
                    }
                    else {
                        result = this.options.favorites ?? [];
                    }
                }
                // Promažu prázdné hodnoty.
                return result.filter(f => f?.trim());
            }
