            /**
             * Uloží oblíbené do uživatelského nastavení.
             *
             * @param {string[] | null} favorites Pole políček, které chceme uložit do uživatelského nastavení. Null nastaví výchozí hodnoty / vymaže uživatelské nastavení.
             */
            _setFavorites(favorites, 
            /**
             * (Default: Aktuální režim filterpanelu) Příznak, zda se ukládá favorites pro simple mód.
             * @type {boolean}
             */
            isSimpleMode) {
                if (!this.gStore) {
                    return;
                }
                //// uložení favorite do gstore
                //if (this.isSimpleMode()) {
                //    //this._setSimpleFavorites(favorites);
                //    this.gStore.set("favoritesSimple." + this.options.idSimpleMode, favorites);  // pokud v gstore nicneni tak použiju defaultní hosnoty
                //} else {
                //    //this.options.favorites = favorites;
                //    this.gStore.set("favorites", favorites);
                //}
                const key = (isSimpleMode ?? this.isSimpleMode())
                    ? `favoritesSimple.${this.options.idSimpleMode}`
                    : 'favorites';
                if (favorites === null) {
                    this.gStore.remove(key);
                    // Vymažu temp, aby se příště načetl znova.
                    this.favoritesTemp = undefined;
                }
                else {
                    this.gStore.set(key, favorites);
                    // Uložím i do tempu, ať se nemusí znovučíst userSettings.
                    this.favoritesTemp = favorites;
                }
            }
