            _setBreadcrumbs(val) {
                if (!Gordic.Utils.WidgetExists('gcontent', this.dlgDetail)) {
                    return;
                }
                // vygenerování názvu
                let textDoTittle = "jres:25030572"; //RC 25030572 : Detail filtru
                const filterpanelName = val?.gfilterpanel_name?.trim();
                const filterpanelPoznamka = val?.gfilterpanel_poznamka?.trim();
                if (filterpanelName) {
                    textDoTittle = textDoTittle + " - " + filterpanelName;
                }
                if (this.staticPoznamka && filterpanelPoznamka) {
                    this.staticPoznamka.update({ caption: "Poznámka: " + filterpanelPoznamka });
                }
                this.dlgDetail.gcontent().setBreadcrumbs({ caption: textDoTittle });
                const typMaskyTxs = val?.typ_masky_txt?.trim();
                if (typMaskyTxs || filterpanelName) {
                    const filterName = "jres:25030548: " + filterpanelName; //RC 25030548 : Uložený filtr
                    if (this.actStatusFilterName) {
                        this.actStatusFilterName.update({ caption: filterName });
                    }
                    if (this.staticFilterName) {
                        this.staticFilterName.update({ caption: filterName });
                    }
                    if (typMaskyTxs) {
                        const typ = "jres:25030033: " + typMaskyTxs; //RC 25030033 : Typ
                        if (this.staticTypFiltru) {
                            this.staticTypFiltru.update({ caption: typ });
                        }
                        if (this.actStatusTypFiltru) {
                            this.actStatusTypFiltru.update({ caption: typ }); //RC 25030033 : Typ
                        }
                    }
                }
            }
            // nastaví model v detilu pokud přijde null dojde k promazání políček
            _setmodelInDetail(value) {
                if (!this.dlgDetail) {
                    return;
                }
                const fieldy = this.dlgDetail.findForms(".js-FormSKriterii").findFields();
                fieldy.gfield("resetValidations");
                fieldy.not(`.${Widget.IgnoreFieldInSavedProfileCustomClass}`).gfield("clear", {
                    filterClear: true,
                    noChange: true
                });
                //that._changeInDetilFilterData(false);
                if (value) {
                    this._setCollectOfDetail(value);
                }
            }
