            /**
             * Přidá či odebere piny pro ovládání oblíbených filtrů
             *
             * @author  DSebesta, TFeik
             * @date    Dávno tomu, 23.03.2022
             */
            _addOrRemoveFavoritePinInDetail(
            /**
             * Příznak, zda se mají piny zobrazit [true] či skrýt.
             * @type {boolean | undefined}
             */
            showPins) {
                if (!this.dlgDetail) {
                    return;
                }
                const rows = this.dlgDetail.findForms(".js-FormSKriterii").findFormRows();
                if (!showPins) {
                    rows.find(".js-favoritePin").remove();
                    return;
                }
                for (let i = 0, length = rows.length; i < length; i++) {
                    // Pokud ma row (nebo jakékoli políčko řádku) classu "noPinnable" tak se u něj neukaze připínák.
                    const $row = rows.eq(i);
                    const noPinnableClass = Widget.filterpanelCustomClasses.noPinnable;
                    if (!$row || $row.hasClass(noPinnableClass) || $row.findFields().hasClass(noPinnableClass)) {
                        continue;
                    }
                    const name = $row.gformrow().data("row");
                    // pokud nemá name nezobrazuju pin
                    if (!name?.trim()) {
                        continue;
                    }
                    const that = this;
                    const isRowFavorite = this._isRowFavorite(name);
                    let supplement = $row.gformrow("findSupplement");
                    // 23.03.2022 - TFeik
                    // Pokud není vyplněn label, pak se nedohledá supplement a tak jej zkusím dohledat znovu (bez závislosti na label).
                    if (supplement.length <= 0) {
                        supplement = $row.find('div.gform-row__supplement');
                    }
                    supplement
                        .addClass("gfilterFavoritePinLabel")
                        .append($('<a>')
                        .addClass('js-favoritePin')
                        .glink({
                        params: {
                            customClass: "g-link--no-underline smartnav-skip",
                            action: new GAction({
                                name: "actPin",
                                caption: null,
                                rowname: name,
                                icon: isRowFavorite
                                    ? "gi-pin gfilterPinTrue"
                                    : "gi-pin gi-rot90 gfilterPinFalse", //"gi-pin", // g-state-text g-state-success
                                tooltip: isRowFavorite
                                    ? "jres:25030551" //RC 25030551 : Odepne tuto podmínku z rychlých podmínek
                                    : "jres:25030552", //RC 25030552 : Připne tuto podmínku do rychlých podmínek
                                run: function (event, actionContext) {
                                    const favorites = that.getFavorites();
                                    if (!this.icon || this.icon.indexOf("90") === -1) {
                                        this.update({
                                            icon: "gi-pin gi-rot90 gfilterPinFalse", //g-state-text g-state-success
                                            tooltip: "jres:25030552" //RC 25030552 : Připne tuto podmínku do rychlých podmínek
                                        });
                                        //that._addRemoveFavorite("remove", this.rowname);
                                        favorites.splice(favorites.indexOf(this.rowname), 1);
                                        //favorites = favorites.filter(f => f !== this.rowname);
                                    }
                                    else {
                                        this.update({
                                            icon: "gi-pin gfilterPinTrue",
                                            tooltip: "jres:25030551" //RC 25030551 : Odepne tuto podmínku z rychlých podmínek
                                        });
                                        const obj = {};
                                        $(event.currentTarget).gformrow().findFields().gfield("model", "collect", obj);
                                        that.aktualnePridavanyOblibenyModel = obj;
                                        that.aktualnePridavanyOblibeny = true;
                                        //that._addRemoveFavorite("add", this.rowname);
                                        favorites.push(this.rowname);
                                    }
                                    that._setFavorites(favorites);
                                    // Nastavím příznak, abych věděl, že mám refreshnout oblíbené.
                                    that.dlgDetailFavoritesChanged = true;
                                }
                            })
                        }
                    }));
                }
            }
            _nastavAddOrRemoveFavoriteZUserSettings() {
                let isChacked = true;
                if (this.gStore) {
                    const storeVal = this.gStore.get("isFavoritesPinPressed", true);
                    if (storeVal === false) {
                        isChacked = false;
                    }
                }
                if (isChacked && this.akceProVyberOblibenych) {
                    this.akceProVyberOblibenych.run({
                        setPending: false
                    });
                }
            }
            // zjištění zda se objekt row nachází v oblíbených
            _isRowFavorite(name) {
                //return this.options.favorites && ($.inArray(name, this.options.favorites) > -1);
                return this.getFavorites().includes(name);
            }
            //// odebrání a přidání oblíbených
            //private _addRemoveFavorite(akce, rowName) {
            //    const that = this;
            //    if (akce === "add") { // přidání do oblíbených
            //        that.options.favorites = that.options.favorites?.concat([rowName]);// přidám do opblíbených
            //        that.refreshFavorite(); // zavolám obnovení
            //    } else if (akce === "remove") {
            //        that.options.favorites =
            //            jQuery.grep(that.options.favorites ?? [], function (value) {
            //                return value !== rowName;
            //            });
            //        that.refreshFavorite();
            //    }
            //}
            //private _vymazatButonInMainRowVisible(visible) {
            //    if (this.vymazatbuttonVisibleParam && visible) {
            //        this.actions.actVymazatKriteria.update({ visible: true });
            //    } else {
            //        this.actions.actVymazatKriteria.update({ visible: false });
            //    }
