            // funkce volaná z venčí. je to manuální nastavení hodnot do filtru
            /**
             * nasetuje object filtru z venku do vnitř a rovnou provede hledání
             *
             * @param {any} [filter] celí model filtru (ne jenom data, pokud mate jen data je potřeba je zabalit do objektu a přidat gfilterpanel_name), možnost nechat null, použije se předchozí
             * @param {boolean} [doNotSearch]
             * @param {boolean | null} [checkIfIsSetDefault]
             * @param {boolean | null} [extendIntoInitialValues]
             * @param {boolean | null} [vymazatTempFilter] // tohle je jen ochcávka protože někdo sprznil tu základní funkci. Do kodu v případě simpleMode přidal načítání z tempu, tkeré tam být nemá.
             */
            applyFilter(filter, doNotSearch, checkIfIsSetDefault, extendIntoInitialValues, vymazatTempFilter) {
                /// <summary>
                /// nasetuje object filtru z venku do vnitř a rovnou provede hledání
                /// </summary>
                /// <param name="filter" type="type">celí model filtru (ne jenom data, pokud mate jen data je potřeba je zabalit do objektu a přidat gfilterpanel_name), možnost nechat null, použije se předchozí</param>
                if (!doNotSearch) {
                    doNotSearch = false;
                }
                // kontrola zda byl nasetovaný defaultní filter, zvolený uživatelem
                if (checkIfIsSetDefault && this.isSetDefaultFilter === true) {
                    return {
                        stav: 0,
                        text: "zrušeno protože je zapnuta kontrola a proběhlo nasetovani uzivatelskym defaultem"
                    };
                }
                this._waitForFavorite() // počkam na load políček ve favorite
                    .done(() => {
                    // 11.09.2020 - TFeik
                    // Je potřeba kontrolovat aktuální hodnotu a nikoli pouze vstupní optiony.
                    //if (that.options.simpleMode) {
                    if (this.isSimpleMode()) {
                        if (vymazatTempFilter) {
                            this.setTempFilter(null);
                        }
                        if (filter == null) { // v případě kdy nepřijde filter
                            if (this.tempFilter?.filter != null) { // při prvním volání se nasavil undefined a přebilo to initialValue =>
                                //19.4.2024 Dsebesta za mě to tady nemá co dělat.Takhle nikdy nemůže dojít k tomu, že se použíjí getcurrentData, 
                                //což mělo přesně simulovat to, že se zavolá jen gfilterpanel("applyFilter") jakoby uživatel klikl tlačítko Načíst. 
                                //Proto tam ted musím dodělat další oser boolean, kterej bude nulovat tempfilter
                                filter = this.tempFilter.filter;
                            }
                            else {
                                filter = this.getCurrentData();
                            }
                        }
                        //12.8.2025 - pnovak - konzultováno s TFeikem, dojde k zabránení cyklení (waitForValues vyvolává change a ta vyvolá opět applyFilter v políčku eko redistribuce)
                        // snad to nic dalšího nerozbije
                        this.element.findFields().gfield("model", "apply", filter, { setFlags: { noChange: true, triggerChange: false } });
                        if (!doNotSearch) {
                            this._callFind(filter, $.Deferred() /*, extendIntoInitialValues ?? false*/);
                        }
                    }
                    else {
                        const $vyberPredvolenychFiltruField = this.element.findFields('vyberPredvolenychFiltru');
                        if (filter == null) { // v případě kdy nepřijde filter
                            filter = this.getCurrentData();
                            $vyberPredvolenychFiltruField.gfield("clear");
                        }
                        else {
                            $vyberPredvolenychFiltruField.gfield("clear"); // v případě kdy bych setoval stejnou hodnotu tomáš nepustí change
                        }
                        // vmaca 4.11.2022 - pokus o použití initialValues při použití uživatelského uloženého filtru
                        if (this.tempFilter?.filter != null && extendIntoInitialValues === true && filter.ixs_mas) {
                            const emptyStoredFields = {}; //tu část filtrů, která se má použít z uložených filtrů musím prvně vynulovat, aby tam nezůstaly initialValues, protože do uložených filtrů se neukládají nully a prázdná pole
                            this.element.findForms().findFields().not(`.${Widget.IgnoreFieldInSavedProfileCustomClass}`).not(`.${Widget.filterpanelCustomClasses.selboxSVyhledanejmaKriteriema}`).gfield('clear', this.createKontroniDivFlags).gfield('model', 'collect', emptyStoredFields);
                            //prvně použiju initialValues, přes to vyresetuju ty, na které se má aplikovat uložený, a nakonec naaplikuju uložený filtr
                            filter = $.extend({}, this.tempFilter.filter, emptyStoredFields, filter);
                            this.element.findFields().gfield("model", "apply", filter, { setFlags: { noChange: true } });
                        }
                        $vyberPredvolenychFiltruField.gfield("setValue", filter, {
                            manualSet: doNotSearch,
                            strictaAtoLoadAfterChoseFilter: true
                        });
                        if (doNotSearch) {
                            this._changeBadgeColor(); // když nehledám změním ikonku 
                        }
                    }
                });
            }
