                // Načítání contentu seznamu přesunuto do samostatné funkce.
                const resizeContent = this.getContentSeznamu();
                //const resizeContent = $.content(this.element);
                if (resizeContent) {
                    const elementForResize = resizeContent.element;
                    Gordic.ResizeManager.unobserve(elementForResize[0], ResizeElementId);
                }
                this.element.empty();
                super._destroy();
