            /**
              * Nastaví hodnotu temp filtru s ohledem na čas požadavku.
              *
              * @author  TFeik
              * @date    16.08.2022
              */
            setTempFilter(
            /**
             * Hodnota filtru.
             * @type {TFilterData | null}
             */
            filter, 
            /**
             * (Default: new Date()) Čas požadavku na vytvoření temp filtru.
             * @type {Date}
             */
            requestCreatedAt) {
                const now = requestCreatedAt ?? new Date();
                const lastTempFilter = this.tempFilter?.createdAt;
                if (lastTempFilter && lastTempFilter >= now) {
                    return;
                }
                this.tempFilter = {
                    filter: filter,
                    createdAt: now
                };
            }
