            /**
             * Překreslí filterpanel s tím, že přenese data v oblíbených.
             *
             * @author  TFeik
             * @date    20.04.2020
             */
            redrawFilterpanel() {
                const currentData = this.getCurrentData();
                this.element.empty();
                this._clearClassProperties();
                this._renderFilterpanel();
                this._setCollectOfFavorite(currentData);
            }
            /**
             * getPoVyhledaniZobrazit
             *
             * @author  TFeik
             * @date    19.05.2020
             *
             * @returns {filterpanelPoVyhledaniZobrazit}
             */
            getPoVyhledaniZobrazit() {
                if (this.poVyhledaniZobrazitTemp == undefined) {
                    // 09.06.2020 - TFeik
                    // Zakázání čtení hodnoty ze storu pokud je zakázáno uživatelské nastavení.
                    if (this.gStore && this.options.poVyhledaniZobrazitUserSettings !== 'Deny') {
                        this.poVyhledaniZobrazitTemp = this.gStore.get(filterpanelUserSettingsKeyOf = 'poVyhledaniZobrazit');
                    }
                    if (this.poVyhledaniZobrazitTemp == undefined) {
                        this.poVyhledaniZobrazitTemp = this.options.poVyhledaniZobrazit;
                    }
                    // 09.06.2020 - TFeik
                    // V případě, že je zakázáno měnit hodnotu v nastavení a nebyla dána z option, pak nastavím natvrdo výchozí.
                    // Vychozí hodnota by jinak byla v options a nepracovalo by se s částmi níže - kterou by to chtělo vyhodit.
                    if (this.poVyhledaniZobrazitTemp == undefined && this.options.poVyhledaniZobrazitUserSettings === 'Deny') {
                        this.poVyhledaniZobrazitTemp = 'VyhledanePodminkyVSelectboxu';
                    }
                    // Starší property a uživatelské nastavení, kterou by bylo jednoho dne krásné vyhodit.
                    if (this.poVyhledaniZobrazitTemp == undefined && this.gStore) {
                        const filtrBadgeVisibleOnly = this.gStore.get('filtrBadgeVisibleOnly');
                        if (filtrBadgeVisibleOnly === true) {
                            this.poVyhledaniZobrazitTemp = 'VyhledanePodminkyVBadge';
                        }
                        else if (filtrBadgeVisibleOnly === false) {
                            this.poVyhledaniZobrazitTemp = 'VyhledanePodminkyVSelectboxu';
                        }
                    }
                    if (this.poVyhledaniZobrazitTemp == undefined && this.gStore) {
                        const poVyhledaniZavritPanelPodminek = this.gStore.get(filterpanelUserSettingsKeyOf = 'poVyhledaniZavritPanelPodminek');
                        if (poVyhledaniZavritPanelPodminek === false) {
                            this.poVyhledaniZobrazitTemp = 'OblibenePodminky';
                        }
                        else if (poVyhledaniZavritPanelPodminek === true) {
                            this.poVyhledaniZobrazitTemp = 'VyhledanePodminkyVSelectboxu';
                        }
                    }
                    if (this.poVyhledaniZobrazitTemp == undefined && this.options.poVyhledaniZavritPanelPodminek === false) {
                        this.poVyhledaniZobrazitTemp = 'OblibenePodminky';
                    }
                    // Pokud nic z předchozího není pak nastavím default.
                    if (this.poVyhledaniZobrazitTemp == undefined) {
                        // 08.07.2020 - TFeik
                        // Pro simple mód nastavím oblíbené, jinak selectbox s vyhledanými.
                        this.poVyhledaniZobrazitTemp = this.isSimpleMode()
                            ? 'OblibenePodminky'
                            : 'VyhledanePodminkyVSelectboxu';
                    }
                    //// 03.06.2020 - TFeik
                    //// Pokud není režim detail a po načtení dat se mají zobrazit oblíbené podmínky,
                    //// které v tomto režimu nejsou, pak nastavím hodnotu z options, eventuálně konstantu.
                    //if (this.poVyhledaniZobrazitTemp === 'OblibenePodminky' && this.getFilterViewMode() !== FilterViewMode.Normal) {
                    //    if (this.options.poVyhledaniZobrazit && this.options.poVyhledaniZobrazit !== 'OblibenePodminky') {
                    //        this.poVyhledaniZobrazitTemp = this.options.poVyhledaniZobrazit;
                    //    }
                    //    else {
                    //        this.poVyhledaniZobrazitTemp = 'VyhledanePodminkyVSelectboxu';
                    //    }
                    //}
                    // 09.06.2020 - TFeik
                    // Přepracování kontroly čtení tak, aby byla kontrolována možnost použít všechny hodnty a ne jenom 'OblibenePodminky'.
                    if (!this.lzePouzitPoVyhledaniZobrazit(this.poVyhledaniZobrazitTemp)) {
                        if (this.options.poVyhledaniZobrazit && this.lzePouzitPoVyhledaniZobrazit(this.options.poVyhledaniZobrazit)) {
                            this.poVyhledaniZobrazitTemp = this.options.poVyhledaniZobrazit;
                        }
                        else if (this.lzeNastavitChovaniZobrazeniPodminekPoVyhledani()) {
                            this.poVyhledaniZobrazitTemp = this.getPoVyhledaniZobrazitSelectoxData()[0].value;
                        }
                        else {
                            console.error('Neplatná kombinace zobrazení údajů po načtení dat a povolení uživatelské změny.', {
                                poVyhledaniZobrazitTemp: this.poVyhledaniZobrazitTemp,
                                poVyhledaniZobrazit: this.options.poVyhledaniZobrazit,
                                poVyhledaniZobrazitUserSettings: this.options.poVyhledaniZobrazitUserSettings
                            });
                        }
                    }
                }
                return this.poVyhledaniZobrazitTemp;
            }
            /**
             * Vrátí příznak, zda již (od vytvoření filterpanelu) prohěhlo vyhledání dat [true].
             *
             * @author  TFeik
             * @date    11.06.2020
             *
             * @returns {boolean} Pokud již bylo hledáno [true], jinak [false].
             */
            wasSearched() {
                // 10.12.2020 - TFeik
                // Zrušen wasSearchedFlag a nahrazen pomocí testování wasSearchedFlag což je standardní cesta pro grid/view.
                return this.confirmedData != null;
            }
            /**
             * Vrátí aktuálně zvolený filtr v selectboxu s filtry.
             *
             * @author  TFeik
             * @date    11.06.2020
             *
             * @param {'getFilterCurrent'} method
             * @returns {JQuery.Promise<Gordic.Widget.filterpanelFilterOptions<TData> | undefined | null>}
             */
            getFilterCurrent() {
                if (!Gordic.Utils.WidgetExists('gfield', this.vyberPredvolenychFiltru)) {
                    return $.Deferred().reject().promise();
                }
                return this.vyberPredvolenychFiltru.gfield('getValueAsync');
            }
            ///**
            // * Vrátí název aktuálně zvoleného filtru.
            // *
            // * @author  TFeik
            // * @date    11.06.2020
            // *
            // * @param {'getFilterCurrentName'} method
            // * @returns {JQuery.Promise<string | undefined | null>}
            // */
            //public getFilterCurrentName(): JQuery.Promise<string | undefined | null> {
            //    return this.getFilterCurrent()
            //        .then(filter => filter?.gfilterpanel_name);
            //}
            /**
             * Vyčistí hodnoty ve filterpanelu (nastaví výchozí).
             *
             * @author  TFeik
             * @date    07.08.2020
             */
            clear() {
                return this._vymazatKriteria();
            }
            /**
             * Vrátí příznak, zda je povoleno odvybrat aktuální výchozí filtr [true], nebo je možné pouze vybrat jiný [false].
             *
             * @author  TFeik
             * @date    17.07.2020
             *
             * @returns {boolean}
             */
            getUnselectFavoriteFilter() {
                if (this.unselectFavoriteFilterTemp == null) {
                    this.unselectFavoriteFilterTemp = this.options.unselectFavoriteFilter;
                    if (this.unselectFavoriteFilterTemp == null) {
                        this.unselectFavoriteFilterTemp = this._getDefaultFilterFromStatic() ? false : true;
                    }
                }
                return this.unselectFavoriteFilterTemp;
            }
            /**
             * Vrátí příznak, zda se "přepínatelné" akce v detailu filtru zobrazí jako checkbox [true].
             *
             * @author  TFeik
             * @date    18.05.2022
             *
             * @returns {boolean}
             */
            getDetailActionAsCheckbox() {
                return this.options.detailActionAsCheckbox ?? true;
            }
            /**
             * Vrátí příznak, zda se má detail fltru po otevření rovnou zafiltrovat na pouze vyplněné [true].
             *
             * @author  TFeik
             * @date    20.07.2020
             *
             * @returns {boolean}
             */
            getZobrazitPouzeVyplneneVDetailuFiltru() {
                if (this.zobrazitPouzeVyplneneVDetailuFiltruTemp == null) {
                    if (this.gStore) {
                        this.zobrazitPouzeVyplneneVDetailuFiltruTemp = this.gStore.get('isChackedSkrytPrazdne');
                    }
                    if (this.zobrazitPouzeVyplneneVDetailuFiltruTemp == null) {
                        this.zobrazitPouzeVyplneneVDetailuFiltruTemp = this.options.zobrazitPouzeVyplneneVDetailuFiltru ?? false;
                    }
                }
                return this.zobrazitPouzeVyplneneVDetailuFiltruTemp;
            }
