(function (Gordic) {
    var Prefabs;
    (function (Prefabs) {
        var Select;
        (function (Select) {
            function time(options) {
                options = $.extend({ step: 30 }, options);
                const data = new Array();
                const step = options.stepMinutes;
                for (let h = 0; h < 24; h++) {
                    for (let m = 0; m < 60; m += step)
                        data.push({ hour: h, minute: m });
                }
                return {
                    data: data,
                    dropdown: true,
                    strict: false,
                    itemTemplate: (d) => { return d ? `${pad(d.hour, 2)}:${pad(d.minute, 2)}` : undefined; },
                    invalidTransform: (s) => {
                        if (typeof s === "string")
                            return parseTime(s);
                        return s;
                    },
                    validators: [
                        {
                            validate: (v) => {
                                if (!v)
                                    return true;
                                let t;
                                if (typeof v === "string")
                                    t = parseTime(v);
                                else
                                    t = v;
                                let h = t.hour;
                                let m = t.minute;
                                return h >= 0 && h < 24 && m >= 0 && m < 60;
                            }
                        }
                    ]
                };
            }
            Select.time = time;
            function parseTime(s) {
                const frags = s.split(':');
                return { hour: parseInt(frags[0] ?? 0), minute: parseInt(frags[1] ?? 0) };
            }
            function pad(n, size) {
                let s = n.toString();
                while (s.length < size)
                    s = "0" + s;
                return s;
            }
        })(Select = Prefabs.Select || (Prefabs.Select = {}));
    })(Prefabs = Gordic.Prefabs || (Gordic.Prefabs = {}));
})(Gordic || (Gordic = {}));
