var Gordic;
(function (Gordic) {
    var Gui;
    (function (Gui) {
        var CustomViewDocumentation;
        (function (CustomViewDocumentation) {
            ///**
            // * IGenerator
            // * 
            // * @author  TFeik
            // * @since   490.1.0.157
            // * @date    12.07.2023
            // */
            //export interface IGenerator {
            //    /**
            //     * CreateMarkdownDescription
            //     * 
            //     * @returns {JQuery.Promise<string>}
            //     */
            //    CreateMarkdownDescription(): JQuery.Promise<string>
            //}
            /**
             * Generator
             *
             * @author  TFeik
             * @since   490.1.0.157
             * @date    12.07.2023
             */
            class Generator {
                /**
                 * createGridColumnsData
                 *
                 * @author  TFeik
                 * @date    11.07.2023
                 *
                 * @param {CreateGridColumnsDataInput} input
                 * @returns {GeneratorGridColumnData[]}
                 */
                static createGridColumnsData(input) {
                    const { gridFormat } = input;
                    const result = [];
                    const gridColumns = gridFormat?.columns;
                    if (gridColumns) {
                        for (let i = 0; i < gridColumns.length; i++) {
                            const gridColumn = gridColumns[i];
                            if (!gridColumn) {
                                continue;
                            }
                            result.push({
                                name: gridColumn.name ?? '',
                                caption: gridColumn.caption ?? '',
                                description: gridColumn.description ?? '',
                                fragment: gridColumn.fragment ?? '*'
                            });
                        }
                    }
                    return result;
                }
                /**
                  * createFormFieldsData
                  *
                  * @author  TFeik
                  * @date    11.07.2023
                  *
                  * @param {CreateFormFieldsDataInput} input
                  * @returns {GeneratorFormFieldData[]}
                  */
                static createFormFieldsData(input) {
                    const { forms } = input;
                    const result = [];
                    if (forms) {
                        Gordic.Utils.Form.ForeachFields(forms, (field, row) => {
                            const fieldOptions = field?.options;
                            if (!fieldOptions) {
                                return;
                            }
                            result.push({
                                name: fieldOptions.name ?? '',
                                caption: row.label ?? '',
                                description: (typeof fieldOptions.tooltip === 'string' ? fieldOptions.tooltip : row.hint) ?? ''
                            });
                        });
                    }
                    return result;
                }
                /**
                 * createActionsData
                 *
                 * @author  TFeik
                 * @date    11.07.2023
                 *
                 * @param {CreateActionsDataInput} input
                 * @returns {GeneratorActionData[]}
                 */
                static createActionsData(input) {
                    const { actions } = input;
                    const result = [];
                    if (actions) {
                        for (let i = 0; i < actions.length; i++) {
                            const action = actions[i];
                            if (!action) {
                                continue;
                            }
                            result.push({
                                name: action.name ?? '',
                                caption: action.caption ?? '',
                                description: action.tooltip ?? ''
                            });
                        }
                    }
                    return result;
                }
                /**
                 * CreateMarkdownRow
                 *
                 * @author  TFeik
                 * @date    12.07.2023
                 *
                 * @param {string[]} texts
                 * @returns {string}
                 */
                static CreateMarkdownRow(texts) {
                    return $.merge([''], texts).join('|');
                }
                /**
                 * CreateMarkdownHaderRow
                 *
                 * @author  TFeik
                 * @date    12.07.2023
                 *
                 * @param {string[]} texts
                 * @returns {string}
                 */
                static CreateMarkdownHaderRow(texts) {
                    return Generator.CreateMarkdownRow(texts.map(i => `=${i}`));
                }
                /**
                 * CreateMarkdownTable
                 *
                 * @author  TFeik
                 * @date    12.07.2023
                 *
                 * @param {CreateMarkdownTableInput} input
                 * @returns {string}
                 */
                static CreateMarkdownTable(input) {
                    const { columnNames, dataRows } = input;
                    const newLine = Generator.NewLine;
                    return ''
                        + Generator.CreateMarkdownHaderRow(columnNames)
                        + newLine
                        + dataRows.map(i => Generator.CreateMarkdownRow(i)).join(newLine);
                }
                /**
                 * CreateMarkdownGridColumnsDescription
                 *
                 * @author  TFeik
                 * @date    12.07.2023
                 *
                 * @param {CreateGridColumnsDataInput} input
                 * @returns {string}
                 */
                static CreateMarkdownGridColumnsDescription(input) {
                    return Generator.CreateMarkdownTable({
                        columnNames: [
                            'jres:32100335', //RC 32100335 : Systémový název
                            'jres:32100336', //RC 32100336 : Název
                            'jres:32100337', //RC 32100337 : Popis
                            'jres:32100338' //RC 32100338 : Fragment
                        ],
                        dataRows: Generator.createGridColumnsData(input).map(i => [
                            i.name,
                            i.caption,
                            i.description,
                            i.fragment
                        ])
                    });
                }
                /**
                 * CreateMarkdownFormFieldsDescription
                 *
                 * @author  TFeik
                 * @date    12.07.2023
                 *
                 * @param {CreateFormFieldsDataInput} input
                 * @returns {string}
                 */
                static CreateMarkdownFormFieldsDescription(input) {
                    return Generator.CreateMarkdownTable({
                        columnNames: [
                            'jres:32100339', //RC 32100339 : Systémový název
                            'jres:32100340', //RC 32100340 : Název
                            'jres:32100341' //RC 32100341 : Popis
                        ],
                        dataRows: Generator.createFormFieldsData(input).map(i => [
                            i.name,
                            i.caption,
                            i.description
                        ])
                    });
                }
                /**
                 * CreateMarkdownActionsDescription
                 *
                 * @author  TFeik
                 * @date    12.07.2023
                 *
                 * @param {CreateActionsDataInput} input
                 * @returns {string}
                 */
                static CreateMarkdownActionsDescription(input) {
                    return Generator.CreateMarkdownTable({
                        columnNames: [
                            'jres:32100342', //RC 32100342 : Systémový název
                            'jres:32100343', //RC 32100343 : Název
                            'jres:32100344' //RC 32100344 : Popis
                        ],
                        dataRows: Generator.createActionsData(input).map(i => [
                            i.name,
                            i.caption,
                            i.description
                        ])
                    });
                }
                /**
                 * CreateMarkdownDescription
                 *
                 * @author  TFeik
                 * @date    12.07.2023
                 *
                 * @param {CreateMarkdownDescriptionInput} input
                 * @returns {string}
                 */
                static CreateMarkdownDescription(input) {
                    const { copyToClipboard } = input;
                    const newLine = Generator.NewLine;
                    const result = ''
                        + Generator.CreateMarkdownBox({
                            header: 'jres:32100332', //RC 32100332 : Sloupečky gridu
                            content: Generator.CreateMarkdownGridColumnsDescription(input)
                        })
                        + newLine
                        + newLine
                        + Generator.CreateMarkdownBox({
                            header: 'jres:32100333', //RC 32100333 : Políčka filtru
                            content: Generator.CreateMarkdownFormFieldsDescription(input)
                        })
                        + newLine
                        + newLine
                        + Generator.CreateMarkdownBox({
                            header: 'jres:32100334', //RC 32100334 : Akce
                            content: Generator.CreateMarkdownActionsDescription(input)
                        });
                    if (copyToClipboard !== false) {
                        Gordic.Utils.copyToClipboard(result);
                    }
                    return result;
                }
                /**
                 * CreateMarkdownBox
                 *
                 * @author  TFeik
                 * @date    12.07.2023
                 *
                 * @param {CreateMarkdownBoxInput} input
                 * @returns {string}
                 */
                static CreateMarkdownBox(input) {
                    const { content, header } = input;
                    const newLine = Generator.NewLine;
                    return ''
                        + `== ${header} ==` + newLine
                        + newLine
                        + '{{box}}' + newLine
                        + content + newLine
                        + '{{/box}}';
                }
            }
            /**
             * Znak pro nový řádek.
             */
            Generator.NewLine = '\n';
            CustomViewDocumentation.Generator = Generator;
        })(CustomViewDocumentation = Gui.CustomViewDocumentation || (Gui.CustomViewDocumentation = {}));
    })(Gui = Gordic.Gui || (Gordic.Gui = {}));
})(Gordic || (Gordic = {}));
