            //	var nextMonth = this.flatpickr.find(".flatpickr-next-month");
            //	// Execute a function when the user releases a key on the keyboard
            //	nextMonth.on("keyup", (event) => {
            //		// Number 13 is the "Enter" key on the keyboard
            //		if (event.keyCode === 13) {
            //			this.flatpickrInstance.changeMonth(1);
            //			nextMonth.focus();
            //			//this.setTabIndex();
            //		}
            //	});
            //	//#endregion
            //}
            onDayCreate(instance) {
                this.initCurrentDate();
                let currentlySelectedDate = this.setSelectDateToValidStringFormat(instance.dateObj, 'YYYY.MM.DD');
                if (this.calendarDayCounter != null) {
                    var trEl = $("<tr>").addClass("g-small-flag-event");
                    $(instance).append(trEl);
                    Object.keys(this.calendarDayCounter).forEach((calendarName) => {
                        Object.keys(this.calendarDayCounter[calendarName]).forEach((date) => {
                            if (date === currentlySelectedDate && this.calendarDayCounter != null) {
                                this.addEventDots(calendarName, this.calendarDayCounter[calendarName][date], trEl);
                            }
                        });
                    });
                }
            }
            //region -- FLATPICKR BALLS ICONS --
            /**
             * vytvoř "ikony" teček na dni v kalendáři
             */
            addEventDots(name, events, tr) {
                if (events === 0)
                    return null;
                var background_color = "#6699FF";
                for (var index = 0; index < this.calendars.length; index++) {
                    var selectCalendar = this.calendars[index];
                    if (selectCalendar.name === name) {
                        background_color = selectCalendar.color;
                    }
                }
                // zde si uložím počet prvků pro daný den (element)
                var trVal = tr.val();
                // pokud je počet prvků (jiných kalendářů) větší než 5, další nezobrazuji (není na to místo)
                if (trVal != null && trVal > 5)
                    return;
                if (events > 0) {
                    // pokud je tedy událostí více a jedná se o první hodnotu, uložím 1
                    if (trVal == null) {
                        tr.val(1);
                    }
                    else {
                        // jinak inkrementuji
                        trVal += 1;
                    }
                    $("<td>")
                        .css({
                        "background-color": background_color
                    })
                        .addClass("g-balls-event")
                        .appendTo(tr);
                }
            }
            //#endregion
            initCurrentDate() {
                if (this.opt.initialDate != null) {
                    this.currentDate = this.opt.initialDate;
                }
                else {
                    if (this.currentDate == null) {
                        this.currentDate = this.flatpickrInstance.now;
                    }
                }
            }
            /** nastavení tabindexů pro práci s klávesnicí */
            //private setTabIndex() {
            //	//this.flatpickr.find(".flatpickr-days").attr("tabindex", 0);
            //	this.flatpickr.find(".flatpickr-day").attr("tabindex", 0);
            //	this.flatpickr.find(".flatpickr-prev-month").attr("tabindex", 0);
            //	this.flatpickr.find(".flatpickr-next-month").attr("tabindex", 0);
            //}
            onValueUpdateFlatpickr(instance) {
                //this.setTabIndex();
                // important row!!!
                this.currentDate = instance.selectedDates["0"];
                this.showEvents(); // zobrazit události
                // focus tlačítek dopředu/dozadu
                if (this.nextDayFocusState === true) {
                    this.nextDay.focus();
                    this.nextDayFocusState = false;
                }
                else if (this.prevDayFocusState === true) {
                    this.prevDay.focus();
                    this.prevDayFocusState = false;
                }
            }
            createEventComponent() {
                if (this.eventList != null)
                    this.eventList.remove();
                this.eventList = $("<div>").addClass("g-event-list").appendTo(this.main);
                this.eventList.addClass("g-tl-scrollable-items").css("overflow", "hidden auto");
                this.eventScrollbar = $("<div>").addClass("g-event-scrollbar").addClass("scrollbar-inner").appendTo(this.eventList);
                //this.createCustomScrollbar();
                this.setActualDay();
            }
            createCustomScrollbar() {
                // thazmuka (3.12.2019) - pokus o fix, kdy se scrollbar vytvořil vpravo mimo kalendář
                if (this.calendars != null) {
                    this.eventScrollbar.mCustomScrollbar({
                        theme: "minimal-dark",
                        callbacks: {
                            onUpdate: function () {
                                // zakázání tabovatelnosti
                                $(this).children().attr("tabindex", -1);
                            }
                        }
                    });
                }
            }
            showEvents() {
                this.createEventComponent();
                this.initEvents();
            }
            initEvents() {
                var eventData = [];
                if (this.calendars != null) {
                    for (let x = 0; x < this.calendars.length; x++) {
                        let calendar = this.calendars[x];
                        if (calendar.active === true) { // pouze aktivní
                            for (let y = 0; y < calendar.data.length; y++) {
                                var event = calendar.data[y];
                                var opt = {
                                    hideDateTime: false
                                };
                                if (calendar.itemTemplate != null) {
                                    // pouzije se vybrany itemTemplate uzivatele, jinak se pouzije default udalosti kalendare
                                    opt = calendar.itemTemplate(opt, event);
                                }
                                else {
                                    var text = event.poznamka == null ? "" : event.poznamka;
                                    var title = event.nazev == null ? "" : event.nazev;
                                    opt.title = title;
                                    opt.text = text;
                                    opt.dat_od = event.dat_od;
                                    opt.dat_do = event.dat_do;
                                    opt.cely_den = event.cely_den;
                                    opt.data = event;
                                }
                                var eventTime = this.setTimeOfEvent(opt);
                                if (eventTime != null) {
                                    opt.time = eventTime;
                                    if (opt.hideDateTime === true)
                                        opt.time = undefined;
                                    eventData.push(opt);
                                }
                            }
                        }
                    }
                }
                if (eventData.length !== 0) {
                    eventData = this.sortDates(eventData);
                    for (let index = 0; index < eventData.length; index++) {
                        var sEvent = eventData[index];
                        this.setOneEvent(sEvent);
                    }
                }
                else {
                    this.setNoEvent();
                }
            }
            /** seřadit data událostí */
            sortDates(events) {
                // řazení dle celých dnů
                events.sort(function (x, y) {
                    return (x.cely_den === y.cely_den) ? 0 : x.cely_den ? -1 : 1;
                });
                // řazení dle data
                events.sort(function (a, b) {
                    if (a.dat_od == null || b.dat_od == null)
                        return -1;
                    let date_a = new Date(a.dat_od);
                    let date_b = new Date(b.dat_od);
                    return date_b - date_a;
                });
                return events;
            }
            setTimeOfEvent(event) {
                var dat_od = event.dat_od;
                var dat_do = event.dat_do;
                var wholeDay = event.cely_den;
                if (dat_od == null || dat_do == null || wholeDay == null)
                    return null;
                let startDate = Gordic.Templates.Formatters.date(dat_od, "yyyy.MM.dd"); // datumy pro porovnání
                let endDate = Gordic.Templates.Formatters.date(dat_do, "yyyy.MM.dd");
                let now = Gordic.Templates.Formatters.date(this.currentDate, "yyyy.MM.dd"); // teď
                var time_text = null;
                var _od = Gordic.Templates.Formatters.date(dat_od, "hh:mm");
                var _do = Gordic.Templates.Formatters.date(dat_do, "hh:mm");
                // jednodenní události
                if ((startDate === endDate) && (startDate === now) && (endDate === now)) {
                    if (wholeDay === 1) { // celý den
                        time_text = "jres:32000306"; //RC 32000306 : Celý den
                    }
                    else {
                        if (dat_od !== dat_do)
                            time_text = _od + "<br>" + _do; // schůzka
                        else
                            time_text = _od; // datum typu milník
                    }
                }
                // vícedenní události
                else {
                    // počáteční den
                    if (startDate === now)
                        time_text = wholeDay === 1 ? "jres:32000306" : _od; //RC 32000306 : Celý den
                    // mezi
                    else if ((startDate < now) && (endDate > now))
                        time_text = "jres:32000306"; //RC 32000306 : Celý den
                    // konečný den
                    else if (endDate === now)
                        time_text = wholeDay === 1 ? "jres:32000306" : //RC 32000306 : Celý den
                            "jres:32000083<br>" + _do; //RC 32000083 : Končí
                }
                return time_text;
            }
