            /**
             * otevřít modální okno filtrů kalendářů
             */
            openFilterModalWindow(element) {
                let contentOfMain = $.content();
                if (this.formFiltersElement != null)
                    this.formFiltersElement.remove();
                // smazat pri kazdem vytvoreni
                this.formFiltersElement = $("<div>");
                this.filterModalWindow = contentOfMain.dialogs.showModalWindow(this.formFiltersElement, null, {
                    width: 420,
                    height: 270,
                    title: "jres:32000086", //RC 32000086 : Filtry kalendářů
                    commandBar: this.createFilterWindowCommandBar()
                });
                this.formFiltersElement.gform("createFrom", this.createFilterPanel());
                this.filterModalWindow.on('close', () => {
                    $(element).focus();
                    this.setAutoCloseToCalendar(true);
                });
            }
            /**
             * vytvoření filterpanelu pro vybrání konkrétního kalendáře
             */
            createFilterPanel() {
                var _this = this;
                let Form = new Gordic.Forms.Form("L1M1S1, L-2-9-1 , M-4-7-1, S-12-12-0, breaks-800-1000");
                Form.addSection("jres:32000087"); //RC 32000087 : Filtry
                if (this.calendars != null) {
                    for (let index = 0; index < this.calendars.length; index++) {
                        Form
                            .addField("gcheck", {
                            initialValue: this.calendars[index].active,
                            //customClass: "w-3",
                            name: this.calendars[index].name,
                            label: this.calendars[index].name,
                            change: function (ev, obj) {
                                _this.setActivity($(this).text(), obj.value);
                                _this.setFilters();
                                _this.flatpickrInstance.setDate(_this.currentDate, true);
                            }
                        });
                    }
                }
                return Form;
            }
            /** nastavím filtry kalendáře */
            setFilters() {
                if (this.calendars != null) {
                    //this.countEventPerDayObj = undefined;
                    this.calendarDayCounter = {};
                    for (let index = 0; index < this.calendars.length; index++) {
                        var event = this.calendars[index];
                        // aktivní kalendář
                        if (event.active === true) {
                            this.addNumberOfEventsPerDay(event.name, this.countAllEventsFromAllCalendars(event));
                        }
                    }
                }
            }
            /** nastavit aktivitu pro vybraný kalendář */
            setActivity(text, value) {
                /** příznak aktivity */
                let flagOfActivity = false;
                if (this.calendars != null) {
                    // přenastavení aktivity kalendáře
                    for (let index = 0; index < this.calendars.length; index++) {
                        if (this.calendars[index].name === text) {
                            this.calendars[index].active = value;
                        }
                        // aktivita je true
                        if (this.calendars[index].active)
                            flagOfActivity = true;
                    }
                }
                // zadny kalendar neni aktivni
                if (!flagOfActivity) {
                    //this.countEventPerDayObj = undefined;
                    this.calendarDayCounter = {};
                }
            }
            createFilterWindowCommandBar() {
                var commandBarActions = new GActionList({
                    actOk: {
                        caption: "jres:25030443", //RC 25030443 : Ok
                        run: () => {
                            this.filterModalWindow.dialog("close");
                        }
                    }
                });
                return commandBarActions.createBar(["actOk"]);
            }
