                    if (_contentArea == null) {
                        console.error("gfilepreview-wopi - contentArea cannot be null");
                        return;
                    }
                    const formId = _contentArea[0].id + '_office_form';
                    const _officeForm = this._officeForm = document.createElement("form");
                    _officeForm.setAttribute('method', "post");
                    _officeForm.setAttribute('target', frameId);
                    _officeForm.setAttribute('id', formId);
                    _officeForm.setAttribute('name', formId);
