                    const { _officeForm, _officeFormAt, _officeFormAte } = this;
                    if (_officeForm == null || _officeFormAt == null || _officeFormAte == null) {
                        console.error("gfilepreview-wopi - office form or its components cannot be null");
                        return;
                    }
                    _officeFormAte.value = data.AccessTokenExpiration.toString();
                    _officeFormAt.value = data.AccessToken;
