            class GRendererCommonUtils {
                static createZoomElement(changeFunc, opts) {
                    const _zoomOptions = opts != null && opts.zoomOptions ? opts.zoomOptions : [
                        { name: "jres:31750004", value: "auto" }, //RC 31750004 : Automatická velikost
                        { name: "jres:31750005", value: 1 }, //RC 31750005 : Skutečná velikost
                        { name: "jres:31750006", value: "page-width" }, //RC 31750006 : Podle šířky
                        { name: "jres:31750007", value: "page-height" }, //RC 31750007 : Podle výšky
                        ...([0.1, 0.5, 0.75, 1, 1.25, 1.5, 2, 3, 4].map((i) => { return { value: i }; }))
                    ];
                    return $.newDiv('pdfzoom').gselectbox({
                        strict: true,
                        dropdown: true,
                        itemTemplate: (val) => {
                            const isNaN = Number.isNaN || function (value) {
                                return value !== value;
                            };
                            if (this == null || _zoomOptions == null || val == null)
                                return "";
                            if (val.name) {
                                return val.name;
                            }
                            else if (isNaN(Number(val.value)) && this != null && _zoomOptions != null && val != null) {
                                const item = _zoomOptions.find(function (item) { return item.value === val.value; });
                                return item != null ? item.name : String(val.value);
                            }
                            else {
                                return (Number(val.value) * 100).toFixed(0) + " %";
                            }
                        },
                        data: _zoomOptions,
                        initialValue: opts && opts.defaultOption != null && _zoomOptions.find((it) => opts.defaultOption === it.value) || _zoomOptions[0],
                        change: changeFunc
                    });
                }
            }
