            class GPdfCanvasHandler {
                constructor(element) {
                    this.element = element;
                    this.drawer = new Components.CanvasDrawer.GCanvasMasterDrawer(element);
                    const that = this;
                    element.off(".pdfcanvashandler");
                    element.on("gfilepreviewloadstart.pdfcanvashandler", function () {
                        that.drawer.unsetContext();
                    });
                    element.on("pdfjspagesinit.pdfcanvashandler", () => {
                        this.drawer.setNewContext();
                    });
                    element.on("pdfjspagerendered.pdfcanvashandler", (ev, ctx) => {
                        if (this.drawer.currentContext == null)
                            return;
                        const canvasId = ctx.pageNumber.toString();
                        const viewPort = ctx.source.viewport;
                        const { viewBox } = viewPort;
                        this.drawer.prepareLayer($(ev.target), canvasId, viewBox[2] - viewBox[0], viewBox[3] - viewBox[1], ctx.source.pdfPageRotate, viewPort.width, viewPort.height, viewPort.rotation);
                    });
                    element.on("pdfjsscalechanging.pdfcanvashandler", (ev, ctx) => {
                        if (this.drawer.currentContext == null)
                            return;
                        const pages = $(ev.target).find(".page");
                        for (let i = 0, ii = pages.length; i < ii; i++) {
                            const jqPage = $(pages[i]);
                            const pageNumber = jqPage.data("page-number");
                            const pageView = ctx.source.getPageView(pageNumber - 1);
                            const rotation = pageView.rotation + pageView.pdfPageRotate;
                            const isRotated = ((Math.abs(rotation) / 90) % 2) === 1;
                            let width, height = 0;
                            if (isRotated) {
                                width = pageView.height || 0;
                                height = pageView.width || 0;
                            }
                            else {
                                width = pageView.width || 0;
                                height = pageView.height || 0;
                            }
                            this.drawer.updateLayerDimensions(pageNumber.toString(), width, height, rotation);
                        }
                    });
                    element.on("gcanvasdraweractive.pdfcanvashandler", (ev, ctx) => {
                        $(ev.target).closest(".page").css("z-index", "2");
                    });
                    element.on("gcanvasdrawerdrop.pdfcanvashandler", (ev, ctx) => {
                        element.find(".page").css("z-index", "");
                        $(ev.target).closest(".page").css("z-index", "2");
                    });
                    element.on("gcanvasdrawercancelactive.pdfcanvashandler", (ev, ctx) => {
                        element.find(".page").css("z-index", "");
                    });
                    element.on("gcanvasdrawerstart.pdfcanvashandler", () => {
                        element.find(".page .textLayer").hide();
                    });
                    element.on("gcanvasdrawerstop.pdfcanvashandler", () => {
                        element.find(".page .textLayer").show();
                    });
                }
                destroy() {
                    this.element.off(".pdfcanvashandler");
                }
            }
            FilePreview.GPdfCanvasHandler = GPdfCanvasHandler;
