            getDataColumns(data) {
                var columns = [];
                $.each(data, (i, item) => {
                    $.each(item, (colName, colValue) => {
                        if (columns.filter((v) => { return v.name == colName; }).length === 0)
                            columns.push({ name: colName, visible: true, filter: false });
                    });
                });
                return columns;
            }
