            applyViewTemplateDataToForm(dialog) {
                if (this.selectedViewTemplate != null && this.selectedViewTemplate.settingsJson != null) {
                    var settingsObj = JSON.parse(this.selectedViewTemplate.settingsJson);
                    //špatně se mi ukládají fragmenty do jsonSettings. Musím si je vytáhnout ze senamu method. (tohle přidám už pro existující šablony pohledů)
                    if (settingsObj != null && settingsObj.fragments != null && settingsObj.fragments.length === 0) {
                        var foundMethods = settingsObj.service.methods.filter(val => { return val.name == settingsObj.methodType; });
                        if (foundMethods.length > 0) {
                            settingsObj.fragments = foundMethods[0].fragments;
                        }
                    }
                    $.extend(true, this.selectedViewTemplate, { dataSourceSettings: settingsObj });
                    dialog.findFields().gfield("model", "apply", this.selectedViewTemplate, { setFlags: { triggerChange: true } }); //, { verificationNeeded: true, initialValues: true });
                }
            }
