            editLayout(enabled) {
                var container = $(this.element).find(".gdashboardpanel_container");
                $(".gdashboardpanel_wrapper").sortable({
                    connectWith: ".gdashboardpanel_wrapper",
                    placeholder: "gdashboard_placeholder"
                }).disableSelection();
                var wrapperLength = container.length;
                if (enabled) {
                    this.options.actions["actDeleteViewCross"].visible(true);
                    //zobrazení obalovacího divu
                    var w = $(this.element).find(".gdashboardpanel_wrapper");
                    w.addClass("gdashboardpanel_wrapper--visible");
                    w.removeClass("gdashboardpanel_wrapper--hidden");
                    $(".gdashboardpanel_wrapper").sortable("enable");
                    this.setEventsOnElements();
                    //označení prvního prvku
                    $(container.closest(".gdashboardpanel_wrapper")[0]).addClass("gdashboardpanel__main--toggled");
                    this.options.actions["actCancelView"].enabled(true);
                    this.options.actions["actEditView"].enabled(false);
                }
                else {
                    //container.unwrap();
                    var cont = $(this.element).find(".gdashboardpanel_container");
                    cont.parent().addClass("gdashboardpanel_wrapper--hidden");
                    var wrappers = $(this.element).find(".gdashboardpanel_wrapper--visible");
                    //$.each(wrappers, (i, item: any) => {
                    //    //$(item).css("width", "calc(" + (100 / wrappers.length) + "%-15px)");
                    //    //$(item).addClass("js-sml").addClass("w-L-" + (12 / wrappers.length)).addClass("w-M-" + (12 / wrappers.length)).addClass("w-S-1");
                    //});
                    this.setZonesWidth();
                    //vypnutí aktivních operací
                    $(".gdashboardpanel_wrapper").sortable("disable");
                    this.element.off("click");
                    this.element.find(".gdashboardpanel_wrapper").off("click");
                    cont.find("*").removeClass("gdashboardpanel__main--toggled");
                    $(this.element).find(".gdashboardpanel_wrapper--visible").removeClass("gdashboardpanel_wrapper--visible");
                    cont.closest(".gdashboardpanel__main--toggled").removeClass("gdashboardpanel__main--toggled");
                    this.options.actions["actCancelView"].enabled(false);
                    this.options.actions["actEditView"].enabled(true);
                    this.options.actions["actDeleteViewCross"].visible(false);
                }
            }
            //nastavá události na jednotlivé elementy
            setEventsOnElements() {
                this.element.find(".gdashboardpanel_wrapper").on("click", (ev) => {
                    ev.stopPropagation();
                    if (!$(ev.target).hasClass("fa-times"))
                        this.toggleSelectedContainer($(ev.target));
                    var s = this.getSelection();
                    this._trigger("selection", ev, [s]);
                });
                this.element.find(".gdashboardpanel_container").on("click", (ev) => {
                    ev.stopPropagation();
                    this.toggleSelectedContainer($(ev.target).closest(".gdashboardpanel_container"));
                    var s = this.getSelection();
                    this._trigger("selection", ev, [s]);
                });
            }
            //označení kontajneru, na který se kliklo
            toggleSelectedContainer(target) {
                this.element.find("*").removeClass("gdashboardpanel__main--toggled");
                //osetreni, pokud uzivatel vymaze pres krizek
                if (!target.hasClass("gdashboardpanel_wrapper"))
                    target = target.closest(".gdashboardpanel_wrapper");
                if (!target.hasClass("gdashboardpanel__main--toggled"))
                    target.addClass("gdashboardpanel__main--toggled");
            }
