            class GDashboardViewUtils {
                //public static prepareSettingsJson(o: IGDashboardViewOptions<any>): string {
                //    //NOTE: Zde ziskam pouze nutne minimum udaju potrebnych pro ulozeni v JSON v DB.
                //    return JSON.stringify({
                //        name: o.name,
                //        description: o.description,
                //        provider: o.provider,
                //        widgetType: o.widgetType,
                //        widgetsOptions: o.widgetsOptions,
                //        columns: GDashboardViewUtils.trimColumns(o.columns),
                //        chart: o.chart,
                //        params: GDashboardViewUtils.trimParams(o.params),
                //        filter: o.filters,
                //        dataSourceSettings: o.dataSourceSettings,
                //        gridUserSettings: o.gridUserSettings,
                //        widgetSize: o.widgetSize,
                //        drillSettings: o["drillSettings"]
                //    });
                //}
                /**  Oreze nepotrebne udaje z parametru na objekt klic:hodnota */
                static trimParams(params) {
                    if (!params)
                        return params;
                    const trimmedParams = new Array();
                    for (let i = 0; i < params.length; i++) {
                        const p = params[i];
                        trimmedParams.push({ name: p["name"], value: p["value"], dataType: p["dataType"], displayValue: p["displayValue"] });
                    }
                    return trimmedParams;
                }
                /** Oreze vlastnosti sloupcu jen na potrebne minimum */
                static trimColumns(cols) {
                    if (!cols)
                        return cols;
                    const dCols = new Array();
                    for (let c of cols) {
                        const colName = c.name;
                        if (!!dCols.find(dc => dc.name === colName))
                            continue;
                        let type = c["type"] ?? c["columnType"] ?? c["dataType"];
                        type = type === "text" ? "string" : type; //NOTE (BM): type === 'text' je v GGridColumn.
                        dCols.push({
                            name: colName,
                            type: type,
                            caption: c.caption,
                            visible: c.visible,
                            cellTemplate: c["cellTemplate"],
                            attributes: c["attributes"],
                            userActions: c["userActions"]
                        });
                    }
                    return dCols;
                }
                static convertColumns(cols) {
                    return (cols ?? []).map(c => GDashboardViewUtils.convertColumn(c));
                }
                static convertColumn(c) {
                    return {
                        name: c.name,
                        caption: c.caption,
                        type: c.dataType,
                        visible: c.visible,
                        attributes: c.attributes
                    };
                }
                static prepareDataSourceSettingsJson(o) {
                    return JSON.stringify({
                        name: o.name,
                        description: o.description,
                        provider: o.provider,
                        //widgetType: o.widgetType,
                        //widgetsOptions: o.widgetsOptions,
                        columns: GDashboardViewUtils.trimColumns(o.columns),
                        //chart: o.chart,
                        params: GDashboardViewUtils.trimParams(o.params),
                        //filter: o.filters,
                        dataSourceSettings: o.dataSourceSettings,
                        //gridUserSettings: o.gridUserSettings,
                        //widgetSize: o.widgetSize,
                        //drillSettings: o["drillSettings"]
                    });
                }
                static prepareViewInTaskSettingsJson(o) {
                    return JSON.stringify({
                        name: o.name,
                        description: o.description,
                        //provider: o.provider,
                        widgetType: o.widgetType,
                        widgetsOptions: o.widgetsOptions,
                        columns: GDashboardViewUtils.trimColumns(o.columns),
                        chart: o.chart,
                        params: GDashboardViewUtils.trimParams(o.params),
                        filter: o.filters,
                        //dataSourceSettings: o.dataSourceSettings,
                        //gridUserSettings: o.gridUserSettings,
                        widgetSize: o.widgetSize,
                        drillSettings: o["drillSettings"],
                        itemTemplate: o.itemTemplate
                    });
                }
                static prepareViewInZoneSettingsJson(o) {
                    return JSON.stringify({
                        //name: o.name,
                        //description: o.description,
                        //provider: o.provider,
                        //widgetType: o.widgetType,
                        //widgetsOptions: o.widgetsOptions,
                        //columns: GDashboardViewUtils.trimColumns(o.columns),
                        //chart: o.chart,
                        params: GDashboardViewUtils.trimParams(o.params),
                        //filter: o.filters,
                        //dataSourceSettings: o.dataSourceSettings,
                        gridUserSettings: o.gridUserSettings,
                        widgetSize: o.widgetSize, //NOTE: Bude i na tasku?
                        //drillSettings: o["drillSettings"]
                        //itemTemplate: o.itemTemplate //NOTE: Nastavitelne pouze pri editaci v tasku?
                    });
                }
                static prepareViewOptions(v) {
                    const templateSettings = JSON.parse(v.dataSourceSettingsJson ?? "{}");
                    const viewInTaskSettings = JSON.parse(v.viewInTaskSettingsJson ?? "{}");
                    const viewInZoneSettings = JSON.parse(v.viewInZoneSettingsJson ?? "{}");
                    const merged = {};
                    if (v.columns && Array.isArray(v.columns))
                        v.columns = GDashboardViewUtils.convertColumns(v.columns);
                    if (v.params && Array.isArray(v.params))
                        $.extend(true, merged, { params: v.params }, { params: viewInTaskSettings.params ?? [] }, { params: viewInZoneSettings.params ?? [] }); //NOTE: Parametry je treba provest deepExtendem, protoze je treba z DB nacist flags a dalsi metadata, ktera jsou menitelna v ADI01
                    return $.extend(/*true,*/ {}, v, templateSettings, viewInTaskSettings, viewInZoneSettings, merged);
                    //return $.extend(true, {}, v, templateSettings, viewInTaskSettings, viewInZoneSettings); //NOTE: Deep extend slouci pole (napr. sloupcu), coz je spatne - nelze to pak konfigurovat!!!
                }
                static prepareViewOptionsWithData(v, providerOptions) {
                    const options = GDashboardViewUtils.prepareViewOptions(v);
                    options.data = GDashboardViewUtils.prepareViewData(options, providerOptions);
                    return options;
                }
                static prepareViewData(o, providerOptions) {
                    const providerName = o.provider;
                    if (!providerName)
                        throw new GError("Missings provider name!");
                    let data;
                    if (providerName.indexOf("custom") > -1) {
                        const provider = Gordic.Dashboard.CustomProviders.find(providerName);
                        if (!provider)
                            throw new GError(`Custom provider ${providerName} was not found (is not registerred).`);
                        data = provider.getData; //function!
                    }
                    else {
                        const provider = Gordic.Dashboard.Providers.find(providerName);
                        if (!provider)
                            throw new GError(`Provider '${providerName}' was not found (is not registerred).`);
                        data = provider.getData($.extend({}, providerOptions, o));
                    }
                    return data;
                }
            }
            WebControls.GDashboardViewUtils = GDashboardViewUtils;
