                    frmt.cellTemplate = Gordic.Templates.ensureTemplate(typeof frmt.cellTemplate === "string" ? frmt.cellTemplate.replace(":@", ":" + frmt.format) : frmt.cellTemplate !== null ? frmt.cellTemplate : field !== null ? "{" + field + (frmt.format ? ":" + frmt.format : "") + "}" : null);
                    frmt.field = field;
                    //frmt.cellTemplate = Gordic.Templates.ensureTemplate(frmt.cellTemplate !== null ? frmt.cellTemplate : frmt.name !== null ? "{" + frmt.name + (format ? ":" + format : "") + "}" : field !== null ? "{" + field + (format ? ":" + format : "") + "}" : null);
                    var rowEl = $("<tr>").addClass("{0}__row".format(this.widgetName));
