                    var rowHeaderEl = $("<td style='padding-left:{0}rem'>".format((level == 0) ? 0.4 : (level * 1.1))).addClass("{0}__cell".format(this.widgetName)).addClass("{0}__header-cell".format(this.widgetName)).appendTo(rowEl);
                    rowHeaderEl.attr("title", frmt.caption);
