                            this.setPending(that.learnCurrentValue(provider, { favorite: true }).then((newFs) => {
                                //const newFs = that.learnValue(provider, { val: favV, favorite: true });
                                const newIdx = newFs.getDef('favCount', 0);
                                that.buildMenu(provider, newFs, dialog, { selectedIdx: newIdx });
                            }));
